'use strict';
const assert = require('node:assert/strict');
const {conflictState,canRetry} = require('../assets/recovery-view.js');
const offline = conflictState({text:true,stale:true,refresh_warning:'offline',can_export_copies:true});
assert.equal(offline.canEdit,true);
assert.equal(offline.canSaveDraft,true);
assert.equal(offline.canResolve,false);
assert.equal(offline.canExport,true);
assert.match(offline.warning,/本机保留的来源/);
assert.match(offline.warning,/保存草稿/);
const fresh = conflictState({text:true,stale:false});
assert.equal(fresh.canResolve,true);
assert.equal(fresh.canExport,false);
assert.equal(fresh.warning,'');
assert.equal(conflictState({text:true},true).canResolve,false);
assert.equal(conflictState({text:false,can_export_copies:true}).canSaveDraft,false);
assert.equal(conflictState({text:false,can_export_copies:true}).canExport,true);
assert.ok(!conflictState({stale:true,refresh_warning:'secret raw CLI output'}).warning.includes('secret'));
assert.equal(canRetry({state:{running:true}},true),true);
assert.equal(canRetry({state:{running:false}},true),false);
assert.equal(canRetry({state:{running:true}},false),false);
console.log('recovery controls preserve offline editing and gate unavailable actions');
